## Secure Partner Exchange Pattern

```java
@RestController
@RequestMapping("/partners")
public class SecurePartnerExchangeController {

    private static final long MAX_PARTNER_XML_SIZE = 5_000_000; // 5MB for partners
    private static final int REQUEST_TIMEOUT_MS = 30_000;

    // SECURE: Implement mutual TLS (mTLS) for partner connections
    @PostMapping("/invoice/submit")
    @Timed(value = "partner.invoice.submission")
    public PartnerResponse submitInvoice(
            @RequestHeader("X-Partner-ID") String partnerId,
            @RequestBody String xmlData) {

        try {
            // Verify client certificate (mTLS)
            if (!isTrustedPartner(partnerId)) {
                return new PartnerResponse("REJECTED", "Untrusted partner");
            }

            // Size check
            if (xmlData.length() > MAX_PARTNER_XML_SIZE) {
                return new PartnerResponse("REJECTED", "Document too large");
            }

            // Parse with timeout
            Document doc = parseWithTimeout(xmlData, REQUEST_TIMEOUT_MS);

            // Schema validation
            validateAgainstPartnerSchema(doc, partnerId);

            // Extract and process
            Invoice invoice = extractInvoice(doc);
            processInvoice(invoice);

            return new PartnerResponse("ACCEPTED", invoice.getId());
        } catch (SecurityException e) {
            return new PartnerResponse("REJECTED", "Security validation failed");
        } catch (TimeoutException e) {
            return new PartnerResponse("REJECTED", "Processing timeout");
        } catch (Exception e) {
            return new PartnerResponse("ERROR", "Processing failed");
        }
    }

    private Document parseWithTimeout(String xmlData, long timeoutMs) 
            throws Exception {

        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // XXE protection
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

        // Namespace awareness improves performance and security
        dbf.setNamespaceAware(true);

        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<Document> future = executor.submit(() -> 
            dbf.newDocumentBuilder().parse(
                new org.xml.sax.InputSource(new StringReader(xmlData))
            )
        );

        try {
            return future.get(timeoutMs, TimeUnit.MILLISECONDS);
        } finally {
            executor.shutdownNow();
        }
    }

